package org.jlinalg.cli;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AccessDeniedException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jlinalg.sequence.MemeMotifInputs;
import org.jlinalg.sequence.TomtomResults;

/** Complete original Tomtom workflow with fresh runtime admission and portable captured verification. */
final class TomtomWorkflow {
    private TomtomWorkflow() { }
    static final String ACTION="Required action: read WARNINGS.md, FAILURE.json when present, metadata/producer.json, OUTPUT-AUDIT.json, PAIR-LEDGER.tsv and process/process.stderr/stdout/ledger. "
        +"SKIP3 means a named exact runtime, permission, dependency or requested input capability is unavailable: supply it through permitted setup or leave the dependent analysis skipped. Analysis never installs. "
        +"FAIL2 means invalid input, integrity, process, capacity, cleanup, cancellation or finalization failure: no result is admitted. Preserve the whole attempt/native worker and retry into NEW paths after correcting the named cause. "
        +"Require overall COMPLETED.json plus tomtom-tools --verify; a component/runtime marker alone is insufficient. Portable verification checks complete captured contracts and integrity, not a current-host ticket, execution authenticity or biological accuracy. "
        +"Do not zero-fill unreported comparisons, infer exact mathematical zero from printed zero, recalculate q-values from reported best matches or silently change source settings/output mode.";
    record Result(Path root,TomtomRecipe.Request request,TomtomOutput.Result output,NextflowFiles.Pin manifest) { }
    static Result start(Path source,Path home,Path build,Path root,Runnable check)throws IOException {
        boolean fresh=false;String stage="CREATE_ATTEMPT";Path nativeWorker=null;
        try{
            TomtomBundle.create(root);fresh=true;Files.createDirectory(root.resolve("metadata"));stage="READ_RECIPE";var request=TomtomRecipe.read(source,check);
            TomtomBundle.write(root.resolve("metadata/attempt.json"),Map.of("schema_version",1,"original_recipe_path",source.toString(),"recipe",MemeRuntimeFiles.pin(request.sourcePin()),"profile",TomtomRecipe.PROFILE,"output_mode",request.mode().name(),"analysis_admitted",false));
            if(home==null||build==null)throw new TomtomRuntime.Unavailable("Exact --home and completed --build-evidence are required. Complete only permitted source/runtime setup, or skip this dependent analysis.");
            stage="DEPENDENCY_PREFLIGHT";MemeNativeHost.read();TomtomRecipe.nativePath(root.toString());TomtomRecipe.nativePath(home.toString());require(!overlap(root,home)&&!overlap(root,build),"Tomtom analysis, original runtime home and original build evidence must be disjoint");
            if(!Files.isDirectory(home,LinkOption.NOFOLLOW_LINKS)||!Files.isDirectory(build,LinkOption.NOFOLLOW_LINKS))throw new TomtomRuntime.Unavailable("Exact original runtime home or completed source/build evidence directory is unavailable. Supply the named permitted dependency; no automatic installation occurred.");
            stage="CAPTURE_INPUTS";var captured=TomtomInputs.capture(root.resolve("prepared"),request,check);stage="CAPTURE_SOURCE_BUILD_EVIDENCE";var originalBuild=MemeBuildEvidence.read(build,new MemeRuntimeFiles.Limits(67108864,268435456,10000),check);TomtomBundle.copyTree(build,root.resolve("build-evidence"),originalBuild.inventory(),originalBuild.limits(),check);
            Files.writeString(root.resolve("WARNINGS.md"),warnings(request,captured.warnings(),List.of(),false),StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            stage="NATIVE_RUNTIME_ADMISSION";var runtime=TomtomRuntime.admit(TomtomRecipe.PROFILE,request.mode(),home,root.resolve("build-evidence"),root.resolve("runtime-admission"),TomtomRuntime.Limits.defaults(),check);runtime.verify(check);
            Path nativeParent=Files.createTempDirectory(root.getParent(),"tomtom-worker-",PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------"))),worker=nativeParent.resolve("process");nativeWorker=worker;TomtomRecipe.nativePath(worker.toString());
            String output=request.mode()==TomtomRecipe.Mode.TEXT?null:worker.resolve("result").toString();var command=request.arguments(home.resolve("bin/tomtom").toString(),captured.query().toString(),captured.targets(),captured.backgroundFile(),output);captured.expected(command);
            var environment=Map.of("PATH",home+"/bin:"+home+"/libexec/meme-5.5.9:/usr/bin:/bin","LANG","C","LC_ALL","C","TZ","UTC");
            TomtomBundle.write(root.resolve("metadata/producer.json"),Map.of("schema_version",1,"profile",TomtomRecipe.PROFILE,"root",root.toString(),"home",home.toString(),"runtime_producer_root",runtime.work().toString(),"process_producer_root",worker.toString(),"command",command,"environment",environment,"accounted_preparation_roots",List.of(root.toString()),"native_worker_retained",true));
            var metadata=MemeRuntimeFiles.tree(root.resolve("metadata"),TomtomBundle.limits(request),check);var warning=NextflowFiles.pin(root.resolve("WARNINGS.md"),1048576,check);
            RsemProcess.Check integrity=()->{request.verify(check);originalBuild.verify(check);require(metadata.equals(MemeRuntimeFiles.tree(root.resolve("metadata"),TomtomBundle.limits(request),check))&&warning.equals(NextflowFiles.pin(root.resolve("WARNINGS.md"),1048576,check)),"Protected original Tomtom request/producer/warnings changed during execution");};
            stage="ORIGINAL_PROCESS";runtime.execute(request,captured,worker,root,integrity,check);integrity.verify();runtime.verify(check);captured.verify(true,check);
            stage="CAPTURE_COMPLETE_NATIVE_OUTPUT";var nativeTree=MemeRuntimeFiles.tree(worker,TomtomBundle.limits(request),check);TomtomBundle.copyTree(worker,root.resolve("process"),nativeTree,TomtomBundle.limits(request),check);TomtomBundle.write(root.resolve("metadata/process-capture.json"),Map.of("producer_root",worker.toString(),"captured_member","process","files",nativeTree,"native_worker_retained",true));
            stage="COMPLETE_INPUT_OUTPUT_AUDIT";var inputs=TomtomCapturedInputs.read(root.resolve("prepared"),root+"/prepared",check);TomtomProcessReceipt.verify(root.resolve("process"),command,request.processLimits(),List.of(root.toString()),check);var result=TomtomOutput.read(root.resolve("process"),inputs,command,check);TomtomOutput.writePairs(root.resolve("PAIR-LEDGER.tsv"),result,check);TomtomBundle.write(root.resolve("OUTPUT-AUDIT.json"),result.document());
            var afterMetadata=new java.util.TreeMap<>(MemeRuntimeFiles.tree(root.resolve("metadata"),TomtomBundle.limits(request),check));require(afterMetadata.remove("process-capture.json")!=null&&metadata.equals(afterMetadata),"Protected original Tomtom producer metadata changed after execution");
            Files.writeString(root.resolve("WARNINGS.md"),warnings(request,captured.warnings(),result.warnings(),Files.size(root.resolve("process/process.stderr"))>0),StandardCharsets.UTF_8,StandardOpenOption.TRUNCATE_EXISTING);
            stage="FINALIZATION";captured.verify(true,check);runtime.verify(check);originalBuild.verify(check);require(nativeTree.equals(MemeRuntimeFiles.tree(worker,TomtomBundle.limits(request),check)),"Original native Tomtom worker changed after capture");
            var files=TomtomBundle.inventory(root,request,check);TomtomBundle.write(root.resolve("manifest.json"),Map.of("schema_version",1,"status","COMPLETE_CAPTURED_ORIGINAL_TOMTOM_CONTRACT","profile",TomtomRecipe.PROFILE,"output_mode",request.mode().name(),"recipe",MemeRuntimeFiles.pin(request.sourcePin()),"files",files,"analysis_admitted",true,"biological_accuracy_certified",false));
            var manifest=NextflowFiles.pin(root.resolve("manifest.json"),67108864,check);TomtomBundle.write(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_ORIGINAL_TOMTOM_ANALYSIS","manifest",MemeRuntimeFiles.pin(manifest),"analysis_admitted",true));
            var completed=TomtomBundle.inventory(root,request,check);var verified=verify(root,check);runtime.verify(check);captured.verify(true,check);originalBuild.verify(check);require(completed.equals(TomtomBundle.inventory(root,request,check))&&nativeTree.equals(MemeRuntimeFiles.tree(worker,TomtomBundle.limits(request),check)),"Complete Tomtom analysis/native worker changed during finalization");return verified;
        }catch(IOException|RuntimeException failure){IOException typed=failure instanceof AccessDeniedException?new TomtomRuntime.Unavailable("Required permitted input/output/runtime access is forbidden: "+failure.getMessage(),failure):failure instanceof IOException io?io:new IOException("Tomtom workflow cancelled or invalid; no result admitted",failure);if(fresh){TomtomBundle.failure(root,stage,typed);if(nativeWorker!=null)try{Files.writeString(root.resolve("WARNINGS.md"),"\nRetained native worker (when created): "+nativeWorker+". Inspect its process.stderr/process.stdout/process.json; original native output is preserved even if capture did not complete.\n",StandardCharsets.UTF_8,StandardOpenOption.APPEND);}catch(IOException diagnostic){typed.addSuppressed(diagnostic);}}throw typed;}
    }
    static Result verify(Path root,Runnable check)throws IOException {
        NextflowFiles.directory(root);check.run();require(!Files.exists(root.resolve("FAILURE.json"),LinkOption.NOFOLLOW_LINKS),"Overall Tomtom workflow retains a failure/skip; component completion is not overall admission");
        var completion=TomtomBundle.json(root.resolve("COMPLETED.json"),65536);require("COMPLETE_ORIGINAL_TOMTOM_ANALYSIS".equals(completion.get("status"))&&Boolean.TRUE.equals(completion.get("analysis_admitted")),"Overall Tomtom completion is absent or not admitted");var pin=NextflowFiles.pin(root.resolve("manifest.json"),67108864,check);require(pin.equals(NextflowFiles.fingerprint(completion.get("manifest"),67108864)),"Overall Tomtom manifest changed");var manifest=TomtomBundle.json(root.resolve("manifest.json"),67108864);
        var request=TomtomRecipe.readCaptured(root.resolve("prepared/recipe.json"),check);require("COMPLETE_CAPTURED_ORIGINAL_TOMTOM_CONTRACT".equals(manifest.get("status"))&&TomtomRecipe.PROFILE.equals(manifest.get("profile"))&&request.mode().name().equals(manifest.get("output_mode"))&&Boolean.TRUE.equals(manifest.get("analysis_admitted"))&&Boolean.FALSE.equals(manifest.get("biological_accuracy_certified"))&&request.sourcePin().equals(NextflowFiles.fingerprint(manifest.get("recipe"),2097152)),"Captured Tomtom overall status/profile/recipe differs");TomtomBundle.verifyInventory(root,manifest.get("files"),request,Set.of("manifest.json","COMPLETED.json"),check);
        var producer=TomtomBundle.json(root.resolve("metadata/producer.json"),2097152);NextflowFiles.keys(producer,"schema_version","profile","root","home","runtime_producer_root","process_producer_root","command","environment","accounted_preparation_roots","native_worker_retained");NextflowFiles.integer(producer.get("schema_version"),1,1);
        String base=NextflowFiles.text(producer.get("root")),home=NextflowFiles.text(producer.get("home")),runtime=NextflowFiles.text(producer.get("runtime_producer_root")),worker=NextflowFiles.text(producer.get("process_producer_root"));for(String name:List.of(base,home,runtime,worker))TomtomRecipe.nativePath(name);
        require(TomtomRecipe.PROFILE.equals(producer.get("profile"))&&runtime.equals(base+"/runtime-admission")&&Boolean.TRUE.equals(producer.get("native_worker_retained"))&&NextflowFiles.strings(producer.get("accounted_preparation_roots")).equals(List.of(base))&&!overlapText(base,home)&&!overlapText(base,worker),"Captured Tomtom runtime/worker/preparation producer mapping differs");
        var expectedEnvironment=Map.of("PATH",home+"/bin:"+home+"/libexec/meme-5.5.9:/usr/bin:/bin","LANG","C","LC_ALL","C","TZ","UTC");require(expectedEnvironment.equals(NextflowFiles.object(producer.get("environment"))),"Captured original Tomtom environment differs");var inputs=TomtomCapturedInputs.read(root.resolve("prepared"),base+"/prepared",check);String output=request.mode()==TomtomRecipe.Mode.TEXT?null:worker+"/result";var command=request.arguments(home+"/bin/tomtom",inputs.query(),inputs.targets(),inputs.backgroundFile(),output);require(command.equals(NextflowFiles.strings(producer.get("command"))),"Complete captured Tomtom scientific command differs");
        var attempt=TomtomBundle.json(root.resolve("metadata/attempt.json"),2097152);NextflowFiles.keys(attempt,"schema_version","original_recipe_path","recipe","profile","output_mode","analysis_admitted");NextflowFiles.integer(attempt.get("schema_version"),1,1);String recipePath=NextflowFiles.text(attempt.get("original_recipe_path"));require(recipePath.startsWith("/")&&recipePath.length()<=32768&&recipePath.chars().noneMatch(c->c<32||c==127)&&TomtomRecipe.PROFILE.equals(attempt.get("profile"))&&request.mode().name().equals(attempt.get("output_mode"))&&Boolean.FALSE.equals(attempt.get("analysis_admitted"))&&request.sourcePin().equals(NextflowFiles.fingerprint(attempt.get("recipe"),2097152)),"Captured original Tomtom attempt/recipe identity differs");
        TomtomRuntimeBundle.verify(root.resolve("runtime-admission"),runtime,home,root.resolve("build-evidence"),base+"/build-evidence",request.mode(),request,check);TomtomProcessReceipt.verify(root.resolve("process"),command,request.processLimits(),List.of(base),check);var result=TomtomOutput.read(root.resolve("process"),inputs,command,check);require(NextflowJson.json(result.document()).equals(NextflowJson.json(TomtomBundle.json(root.resolve("OUTPUT-AUDIT.json"),16777216))),"Captured Tomtom complete output audit differs");TomtomOutput.verifyPairs(root.resolve("PAIR-LEDGER.tsv"),result,check);
        var capture=TomtomBundle.json(root.resolve("metadata/process-capture.json"),67108864);require(worker.equals(capture.get("producer_root"))&&"process".equals(capture.get("captured_member"))&&Boolean.TRUE.equals(capture.get("native_worker_retained"))&&NextflowJson.json(TomtomBundle.portable(TomtomBundle.recorded(capture.get("files")))).equals(NextflowJson.json(TomtomBundle.portable(TomtomBundle.inventory(root.resolve("process"),request,check)))),"Complete captured original worker census differs");
        require(NextflowFiles.utf8(NextflowFiles.bytes(root.resolve("WARNINGS.md"),1048576)).equals(warnings(request,inputs.warnings(),result.warnings(),Files.size(root.resolve("process/process.stderr"))>0)),"Complete Tomtom warnings/required actions changed or were suppressed");
        TomtomBundle.verifyInventory(root,manifest.get("files"),request,Set.of("manifest.json","COMPLETED.json"),check);require(pin.equals(NextflowFiles.pin(root.resolve("manifest.json"),67108864,check)),"Overall Tomtom manifest changed during portable verification");return new Result(root,request,result,pin);
    }
    private static String warnings(TomtomRecipe.Request request,List<String> inputWarnings,List<String> outputWarnings,boolean stderr){
        String base="# Tomtom warnings and required actions\n\nWARNING: Exact original5.5.9 fitted comparisons; historical paper settings/inputs and biological accuracy are not certified. Declared native process limits do not guarantee the verifier JVM heap; use sufficient permitted Java memory for complete inputs/results.\n\nWARNING: Original q-values use the complete tested orientation family, not only reported best matches. PAIR-LEDGER.tsv preserves unavailable numeric values as NA for unreported pairs. Printed zero can be floating-point underflow.\n\nWARNING: Requested output mode="+request.mode()+". Original input files are unchanged; staged command paths and producer locations are recorded explicitly. The native worker is retained for recovery; its recorded path is not opened by portable verification.\n\n";
        var notes=new java.util.LinkedHashSet<String>();for(String note:inputWarnings)if(!note.startsWith("INPUT_COMPONENT_ONLY:")&&!note.startsWith("REQUIRED ACTION: these are captured inputs only."))notes.add(note);for(String note:outputWarnings)if(!note.startsWith("OUTPUT_CONTRACT_ONLY:")&&!note.startsWith("TEXT_OUTPUT_CONTRACT_ONLY:"))notes.add(note);
        for(String note:notes)base+="WARNING: "+note+"\n\n";if(stderr)base+="WARNING: Original Tomtom emitted stderr. Read the complete process/process.stderr, including original small-database and numerical warnings; exit0 does not remove them.\n\n";return base+ACTION+"\n";
    }
    private static boolean overlap(Path a,Path b){return a.startsWith(b)||b.startsWith(a);}
    private static boolean overlapText(String a,String b){return a.equals(b)||a.startsWith(b+"/")||b.startsWith(a+"/");}
    private static void require(boolean value,String message)throws IOException {MemeRuntimeFiles.require(value,message);}
}
